// Solo lo que el cliente escribe por WhatsApp. El chat web (inbox API) lo atiende el bot "Iagro bot".
// Acepta los dos avisos de Chatwoot:
//  - Webhook (Integraciones → Webhooks, "Mensaje creado"): el cuerpo es el mensaje, con la conversación adentro.
//  - Automatización ("Enviar evento de webhook"): el cuerpo es la conversación, con su último mensaje en messages[].
const b = $json.body || {};
let conv, msg;
if (b.event === 'message_created') {
  conv = b.conversation || {};
  msg = b;
} else if (String(b.event || '').startsWith('automation_event.')) {
  conv = b;
  msg = (b.messages || [])[(b.messages || []).length - 1] || {};
} else {
  return [];
}
const entrante = msg.message_type === 'incoming' || msg.message_type === 0;
if (!entrante || msg.private === true) return [];
if (conv.channel !== 'Channel::Whatsapp') return [];

// Botones de la plantilla de alertas ("Dejar de recibir", "ALTA"…): los atiende "IAGRO · Seguimiento de estados"
const t = String(msg.content || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/^[^a-z0-9]+/, '').trim();
if (/^(dejar de recibir|no recibir alertas|desactivar alertas|activar alertas|recibir alertas|alta|solo lluvias fuertes|lluvias fuertes)$/.test(t)) return [];

// Un agente atiende el chat en Chatwoot (misma regla que el bot): etiqueta "humano",
// o asignado a un agente que lo abrió en las últimas 6 h
const etiquetas = (conv.labels || []).map((x) => String(x).toLowerCase());
const vistoAgente = Number(conv.agent_last_seen_at || 0) * 1000;
if (etiquetas.includes('humano')) return [];
if (conv.meta?.assignee && vistoAgente > Date.now() - 6 * 3600 * 1000) return [];

const sender = conv.meta?.sender || b.sender || {};
const telefono = String(sender.phone_number || '').replace(/\D/g, '');
if (telefono.length < 8 || !conv.id) return [];
return [{ json: { telefono, conversation_id: conv.id, nombre_whatsapp: String(sender.name || '').trim() } }];

// Texto y enlace personal del mensaje "Ver pronóstico"
const d = $('Solo WhatsApp entrante').first().json;
const cfg = $('Configuración').first().json.cfg || {};
const r = $json;
if (!r.enviar || !r.enlace) return [];   // ya se lo mandamos hace menos de 30 min: no se repite

// Nombre del perfil de WhatsApp (si no es solo un número); si no, el registrado en el panel
const deWhatsapp = /[a-záéíóúñ]/i.test(d.nombre_whatsapp) ? d.nombre_whatsapp : '';
const nombre = String(deWhatsapp || r.nombre_cliente || 'productor').replace(/\s+/g, ' ').trim().slice(0, 60);

return [{ json: {
  base: String(cfg.chatwoot_url_publica || '').replace(/\/+$/, '') + '/api/v1/accounts/' + cfg.chatwoot_account_id,
  inbox: Number(cfg.chatwoot_inbox_id || 0),
  conversation_id: d.conversation_id,
  telefono: d.telefono,
  url: 'https://iagro360.xyz/l/' + r.enlace,
  texto: 'Hola ' + nombre + ',\n\nTu pronóstico de IAGRO 360 está listo.\n\nToca el botón para ver tu pronóstico actualizado, alertas y lluvia acumulada de tu zona.',
} }];

// Mensaje de servicio con botón de enlace (interactive "cta_url" de la API de WhatsApp Cloud).
// Va directo a Meta: Chatwoot no envía botones de enlace. Es gratis dentro de las 24 h después
// de que el cliente escribió. El token y el número salen del inbox de WhatsApp de Chatwoot.
const p = $('Preparar').first().json;
const pc = $json.provider_config || {};
if (!pc.api_key || !pc.phone_number_id) return [{ json: { ...p, meta: null } }];   // → texto con el enlace
return [{ json: { ...p, meta: {
  url: 'https://graph.facebook.com/v24.0/' + pc.phone_number_id + '/messages',
  token: pc.api_key,
  cuerpo: {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: p.telefono,
    type: 'interactive',
    interactive: {
      type: 'cta_url',
      body: { text: p.texto },
      action: { name: 'cta_url', parameters: { display_text: 'Ver pronóstico', url: p.url } },
    },
  },
} } }];
